# bridge_to_aster.py
# Responsibility: generates study.comm and study.export from model_data
# (output of bridge_from_liml.extract_aster_data_from_liml(), then
# aligned with the mesh by bridge_mesh.write_mesh()).
#
# Architecture:
#   - SOLVER_BUILDERS_ASTER maps each solver keyword to a builder function.
#     New analysis type = new builder + entry in SOLVER_BUILDERS_ASTER +
#     new template (path in CONFIG_BRIDGE["analyses"][...]["template"]).
#   - generate_AsterSolver_files() is the public dispatcher; it selects the
#     builder from the "solver_command" of the active analysis
#     (get_active_analysis()).
#
# Template placeholders generated by _build_lin_static():
#   {defigroup_block}      DEFI_GROUP (+ CREA_MAILLAGE / MODI_MAILLAGE)
#   {model_block}          AFFE_MODELE (per elset, mixed dimensions)
#   {cara_elem_block}      AFFE_CARA_ELEM (beam / shell / spring sections)
#   {materials_block}      DEFI_MATERIAU per material (incl. RHO)
#   {fieldmat_block}       AFFE_MATERIAU assignment
#   {loads_block}          AFFE_CHAR_MECA with BCs, loads and couplings
#   {cara_elem_ref}        "    CARA_ELEM=cara,\n" or "" in MECA_STATIQUE
#   {solveur_ref}          "    SOLVEUR=_F(METHODE=.., ..),\n    INFO=2,\n"
#                          (_build_lin_solveur_ref, setting lin_solver)
#   {calc_champ_block}     CALC_CHAMP (depends on element type)
#   {postreleve_block}     POST_RELEVE_T tables
#   {impr_table_block}     IMPR_TABLE calls
#   {impr_resu_block}      IMPR_RESU MED (only with "med_export")
#
# Compatible with IronPython 2.7.9.

